<script lang="ts">
 import type {Target,Cadence} from '$lib/budget/types';import type {Category} from '$lib/types';import {formatMoney,formatDate} from '$lib/utils';
 import Editor from './TargetEditor.svelte';import CategoryPill from './CategoryPill.svelte';import Badge from './FinancialBadge.svelte';
 let {targets,categories,budgets,month,revision,commandKey}:{targets:Target[];categories:Category[];budgets:{id:number;category_id:number;period:string;limit_cents:number}[];month:string;revision:number;commandKey:string}=$props();
 const eligible=$derived(categories.filter(c=>c.type!=='income'&&!categories.some(child=>child.parent_id===c.id)));
 const available=$derived(eligible.filter(c=>!targets.some(t=>t.categoryId===c.id)));
 const drafts=$derived(budgets.filter(b=>available.some(c=>c.id===b.category_id)));
 const cadenceNames={monthly:'Monthly',weekly:'Weekly',annual:'Annual',irregular:'Custom date / balance'};
 const legacyCadence=(p:string):Cadence|undefined=>p==='month'?'monthly':p==='week'?'weekly':p==='year'?'annual':undefined;
</script>
<details class="product-panel target-settings" id="target-settings" open={!targets.length}><summary class="product-panel-header"><div><h2>Targets and due dates</h2><p class="product-row-caption">{targets.length} configured · intent, not allocated cash</p></div><span aria-hidden="true">⌄</span></summary>
 <div class="product-panel-body"><p>Set a cadence, deadline and effective month. Saving a target does not move or assign money.</p></div>
 {#each targets as t(t.id)}{@const c=categories.find(c=>c.id===t.categoryId)}<details class="target-item"><summary class="product-row"><div class="product-row-main"><CategoryPill id={t.categoryId} name={c?.name??'Category unavailable'} color={c?.color}/><span class="product-row-caption">{cadenceNames[t.cadence]} · starts {formatDate(t.startDate)}{#if t.dueDate} · due {formatDate(t.dueDate)}{/if}</span></div><Badge value={formatMoney(t.amountCents)} label="Target amount"/></summary><Editor target={t} categories={eligible} {month} {revision} {commandKey}/></details>{/each}
 {#if available.length}<details class="target-item" id="new-target"><summary class="product-row"><span class="product-row-title">Add a target</span></summary><Editor categories={available} {month} {revision} {commandKey}/></details>{/if}
 {#if drafts.length}<section class="legacy-drafts"><header class="product-panel-header"><h3>Existing limits to review</h3></header><p class="product-panel-body">Use an existing limit as a starting point. The old record is preserved; no money is assigned.</p>{#each drafts as b(b.id)}{@const c=categories.find(c=>c.id===b.category_id)!}{@const cadence=legacyCadence(b.period)}<details class="target-item" id={`legacy-target-${b.id}`}><summary class="product-row"><div class="product-row-main"><CategoryPill id={c.id} name={c.name} color={c.color}/><span class="product-row-caption">Existing {b.period} limit</span></div><Badge value={formatMoney(b.limit_cents)} label="Existing limit"/></summary>{#if cadence}<Editor categories={available} draft={{categoryId:b.category_id,amountCents:b.limit_cents,cadence}} {month} {revision} {commandKey}/>{:else}<p class="product-panel-body">This cadence needs review. Add a new target explicitly instead.</p>{/if}</details>{/each}</section>{/if}
</details>
<style>.target-settings>summary{list-style:none;cursor:pointer;min-height:60px}.target-item{border-top:1px solid var(--border)}.target-item>summary{cursor:pointer;list-style:none;min-height:56px}.target-item>summary::-webkit-details-marker,.target-settings>summary::-webkit-details-marker{display:none}.target-settings{scroll-margin-top:120px}.legacy-drafts{border-top:1px solid var(--border)}</style>
